struct Services {
    ConnectionPool pool;                       // RAII: released in ~Services
    explicit Services(const Config& cfg)
        : pool(cfg, /*min_idle=*/8) { pool.validate(); }
};

int main() {
    Services svc{Config::load()};   // acquired before the first deadline
    return serve(svc);
}

